arc_modules_import_command:
import importlib, json, sys
mods = ['carnot.agentic.arc_agi3_world_model', 'carnot.agentic.arc_world_model_synth', 'carnot.agentic.arc_world_model_dsl']
out = {}
for mod in mods:
    try:
        importlib.import_module(mod)
        out[mod] = {'import_ok': True, 'error': None}
    except Exception as exc:
        out[mod] = {'import_ok': False, 'error': repr(exc)}
print(json.dumps(out, sort_keys=True))
sys.exit(0 if all(v['import_ok'] for v in out.values()) else 1)
